Layout__LandingPage.Content:
{% style name: "font-awesome", version: "5" %}
{% style name: "ugptheme-fonts" %}
<!DOCTYPE html>
<html lang="{{ Culture.Name }}">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>{% page_title Site.SiteName, position: "before", separator: " - " %}</title>
    <link type="image/x-icon" rel="shortcut icon" href="{{ "~/UgpTheme/assets/favicon.ico" | href }}">
    {% resources type: "Meta" %}
    {% resources type: "HeadLink" %}
    {% resources type: "Stylesheet" %}
    {% resources type: "HeadScript" %}
    <style>
        :root {
            --lp-ink: #0d1b2a;
            --lp-ink-2: #16283d;
            --lp-teal: #0085a1;
            --lp-teal-light: #5fd3ea;
            --lp-coral: #ff6b4a;
            --lp-paper: #f5f7fa;
            --lp-line: #e2e7ee;
            --lp-text: #1f2933;
            --lp-muted: #5b6875;
            --lp-radius: 14px;
            --lp-top-h: 68px;
        }
        *, *::before, *::after { box-sizing: border-box; }
        html { scroll-behavior: smooth; }
        body.lp {
            margin: 0;
            background: #fff;
            color: var(--lp-text);
            font-family: "Open Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
            font-size: 17px;
            line-height: 1.65;
            -webkit-font-smoothing: antialiased;
        }
        .lp img { max-width: 100%; height: auto; display: block; }
        .lp a { color: var(--lp-teal); }
        .lp h1, .lp h2, .lp h3 { line-height: 1.2; margin: 0 0 .5em; color: inherit; font-weight: 800; letter-spacing: -.01em; }
        .lp [id] { scroll-margin-top: calc(var(--lp-top-h) + 16px); }
        .lp-wrap { width: 100%; max-width: 1140px; margin: 0 auto; padding: 0 20px; }

        /* ---------- Top bar ---------- */
        .lp-top {
            position: sticky; top: 0; z-index: 50;
            background: rgba(255, 255, 255, .92);
            backdrop-filter: saturate(160%) blur(10px);
            -webkit-backdrop-filter: saturate(160%) blur(10px);
            border-bottom: 1px solid var(--lp-line);
        }
        .lp-top .lp-wrap { display: flex; align-items: center; gap: 24px; height: var(--lp-top-h); }
        .lp-logo img { height: 38px; width: auto; }
        .lp-nav { display: flex; gap: 4px; margin-left: auto; overflow-x: auto; scrollbar-width: none; }
        .lp-nav::-webkit-scrollbar { display: none; }
        .lp-nav a {
            white-space: nowrap; padding: 8px 12px; border-radius: 999px;
            font-size: 14px; font-weight: 600; color: var(--lp-muted); text-decoration: none;
            transition: background .15s, color .15s;
        }
        .lp-nav a:hover, .lp-nav a.is-active { background: var(--lp-paper); color: var(--lp-ink); }
        .lp-top-cta { flex-shrink: 0; }
        @media (max-width: 860px) {
            .lp-top .lp-wrap { display: grid; grid-template-columns: 1fr auto; height: auto; padding-top: 10px; gap: 6px 16px; }
            .lp-nav { grid-column: 1 / -1; grid-row: 2; min-width: 0; margin: 0; padding-bottom: 8px; }
            .lp-logo img { height: 32px; }
        }

        /* ---------- Buttons ---------- */
        .lp-btn {
            display: inline-flex; align-items: center; gap: 8px;
            padding: 12px 22px; border-radius: 999px; border: 2px solid transparent;
            font-weight: 700; font-size: 15px; text-decoration: none; line-height: 1.2;
            transition: transform .15s, background .15s, border-color .15s, color .15s;
        }
        .lp-btn:hover { transform: translateY(-1px); }
        .lp .lp-btn-primary { background: var(--lp-coral); color: #fff; }
        .lp .lp-btn-primary:hover { background: #ff5530; color: #fff; }
        .lp .lp-btn-ghost { border-color: rgba(255, 255, 255, .35); color: #fff; }
        .lp .lp-btn-ghost:hover { border-color: #fff; color: #fff; }
        .lp .lp-btn-sm { padding: 8px 16px; font-size: 14px; }

        /* ---------- Hero ---------- */
        .lp-hero {
            position: relative; overflow: hidden; color: #fff;
            background:
                radial-gradient(900px 500px at 85% -10%, rgba(0, 133, 161, .55), transparent 60%),
                radial-gradient(700px 400px at -10% 110%, rgba(255, 107, 74, .25), transparent 60%),
                linear-gradient(160deg, var(--lp-ink) 0%, var(--lp-ink-2) 100%);
            padding: 88px 0 96px;
        }
        .lp-hero::before {
            content: ""; position: absolute; inset: 0; pointer-events: none;
            background-image: linear-gradient(rgba(255,255,255,.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.05) 1px, transparent 1px);
            background-size: 48px 48px;
            mask-image: linear-gradient(to bottom, #000 0%, transparent 85%);
            -webkit-mask-image: linear-gradient(to bottom, #000 0%, transparent 85%);
        }
        .lp-hero-grid { position: relative; display: grid; grid-template-columns: 1.25fr 1fr; gap: 56px; align-items: center; }
        .lp-eyebrow { margin: 0 0 16px; font-size: 13px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--lp-teal-light); }
        .lp-hero h1 { font-size: clamp(38px, 6vw, 64px); margin-bottom: 16px; }
        .lp-sub { font-size: clamp(18px, 2.2vw, 22px); color: rgba(255, 255, 255, .8); margin: 0 0 28px; max-width: 34em; }
        .lp-meta { list-style: none; padding: 0; margin: 0 0 32px; display: flex; flex-wrap: wrap; gap: 10px; }
        .lp-meta li {
            display: inline-flex; align-items: center; gap: 8px;
            padding: 8px 14px; border-radius: 999px;
            background: rgba(255, 255, 255, .08); border: 1px solid rgba(255, 255, 255, .14);
            font-size: 15px; font-weight: 600;
        }
        .lp-meta i { color: var(--lp-teal-light); }
        .lp-actions { display: flex; flex-wrap: wrap; gap: 12px; }
        .lp-hero-media img { border-radius: var(--lp-radius); box-shadow: 0 30px 60px -20px rgba(0, 0, 0, .6); width: 100%; }
        @media (max-width: 860px) {
            .lp-hero { padding: 56px 0 64px; }
            .lp-hero-grid { grid-template-columns: 1fr; gap: 36px; }
        }

        /* ---------- Body sections (used by the HtmlBodyPart) ---------- */
        .lp-section { padding: 80px 0; }
        .lp-section--alt { background: var(--lp-paper); }
        .lp-section--dark { background: var(--lp-ink); color: #fff; }
        .lp-kicker { display: block; margin-bottom: 10px; font-size: 13px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--lp-teal); }
        .lp-section h2 { font-size: clamp(28px, 3.6vw, 40px); max-width: 22em; }
        .lp-lead { font-size: 20px; color: var(--lp-text); max-width: 40em; }
        .lp-muted { color: var(--lp-muted); }
        .lp-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; margin-top: 32px; }
        .lp-cols p { margin: 0 0 1em; }
        .lp-quote {
            margin: 0; padding: 28px 32px; border-left: 4px solid var(--lp-coral);
            background: #fff; border-radius: 0 var(--lp-radius) var(--lp-radius) 0;
            font-size: 21px; font-weight: 600; line-height: 1.5; color: var(--lp-ink);
            box-shadow: 0 10px 30px -18px rgba(13, 27, 42, .35);
        }
        .lp-cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; margin-top: 36px; counter-reset: lpcard; }
        .lp-card {
            position: relative; padding: 28px 28px 24px 84px; background: #fff;
            border: 1px solid var(--lp-line); border-radius: var(--lp-radius);
            transition: border-color .15s, box-shadow .15s;
        }
        .lp-card:hover { border-color: var(--lp-teal); box-shadow: 0 14px 30px -20px rgba(0, 133, 161, .6); }
        .lp-card::before {
            counter-increment: lpcard; content: counter(lpcard, decimal-leading-zero);
            position: absolute; left: 26px; top: 26px; font-size: 26px; font-weight: 800; color: var(--lp-teal);
        }
        .lp-card h3 { font-size: 20px; }
        .lp-card p { margin: 0; color: var(--lp-muted); }
        .lp-note { margin-top: 28px; padding: 20px 24px; border-radius: var(--lp-radius); background: rgba(0, 133, 161, .08); color: var(--lp-ink); }

        .lp-agenda { list-style: none; margin: 36px 0 0; padding: 0; border-top: 1px solid var(--lp-line); }
        .lp-agenda li { display: grid; grid-template-columns: 150px 1fr; gap: 24px; padding: 20px 0; border-bottom: 1px solid var(--lp-line); }
        .lp-agenda time { font-weight: 700; color: var(--lp-ink); font-variant-numeric: tabular-nums; }
        .lp-agenda h3 { font-size: 18px; margin: 0 0 4px; }
        .lp-agenda p { margin: 0; color: var(--lp-muted); font-size: 16px; }
        .lp-agenda .is-break { background: var(--lp-paper); padding-left: 16px; padding-right: 16px; border-radius: 10px; border-bottom-color: transparent; }
        .lp-agenda .is-break h3 { font-weight: 600; color: var(--lp-muted); }
        .lp-tag {
            display: inline-block; margin-bottom: 6px; padding: 2px 10px; border-radius: 999px;
            font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
            background: rgba(0, 133, 161, .1); color: var(--lp-teal);
        }
        .lp-tag--panel { background: rgba(255, 107, 74, .12); color: #d84a2b; }
        .lp-hosts { display: flex; flex-wrap: wrap; gap: 12px 32px; margin-top: 24px; color: var(--lp-muted); font-size: 15px; }
        .lp-hosts strong { color: var(--lp-ink); }

        .lp-gallery { columns: 2; column-gap: 20px; margin-top: 36px; }
        .lp-gallery img { width: 100%; margin: 0 0 20px; border-radius: var(--lp-radius); break-inside: avoid; }

        .lp-partners { display: grid; gap: 36px; margin-top: 36px; }
        .lp-partners h3 { font-size: 13px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--lp-muted); margin-bottom: 14px; }
        .lp-chips { display: flex; flex-wrap: wrap; gap: 12px; list-style: none; margin: 0; padding: 0; }
        .lp-chips li {
            padding: 14px 22px; background: #fff; border: 1px solid var(--lp-line); border-radius: 12px;
            font-weight: 700; color: var(--lp-ink);
        }
        .lp-chips--main li { border-color: var(--lp-teal); }

        @media (max-width: 860px) {
            .lp-section { padding: 56px 0; }
            .lp-cols, .lp-cards { grid-template-columns: 1fr; gap: 20px; }
            .lp-agenda li { grid-template-columns: 1fr; gap: 6px; }
            .lp-gallery { columns: 1; }
        }

        /* ---------- Closing CTA ---------- */
        .lp-cta {
            padding: 80px 0; color: #fff; text-align: center;
            background: radial-gradient(700px 300px at 50% 0%, rgba(0, 133, 161, .5), transparent 70%), var(--lp-ink-2);
        }
        .lp-cta h2 { font-size: clamp(28px, 4vw, 44px); margin-bottom: 12px; }
        .lp-cta p { color: rgba(255, 255, 255, .75); margin: 0 auto 28px; max-width: 36em; }

        /* ---------- Footer ---------- */
        .lp-foot { background: var(--lp-ink); color: rgba(255, 255, 255, .7); font-size: 15px; }
        .lp-foot-grid { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 48px; padding: 64px 0 40px; }
        .lp-foot h4 { margin: 0 0 14px; font-size: 13px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: #fff; }
        .lp-foot ul { list-style: none; margin: 0; padding: 0; }
        .lp-foot li { margin-bottom: 8px; }
        .lp .lp-foot a { color: rgba(255, 255, 255, .8); text-decoration: none; }
        .lp .lp-foot a:hover { color: #fff; }
        .lp-foot-logo { display: inline-block; padding: 10px 14px; background: #fff; border-radius: 10px; margin-bottom: 16px; }
        .lp-foot-logo img { height: 34px; width: auto; }
        .lp-foot-about { max-width: 30em; margin: 0; }
        .lp-social { display: flex; flex-wrap: wrap; gap: 10px; }
        .lp-social a {
            display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px;
            border-radius: 50%; background: rgba(255, 255, 255, .08); transition: background .15s;
        }
        .lp .lp-social a:hover { background: var(--lp-teal); }
        .lp-foot-bottom {
            display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px 24px;
            padding: 20px 0 28px; border-top: 1px solid rgba(255, 255, 255, .1); font-size: 13px;
        }
        .lp-legal { display: flex; flex-wrap: wrap; gap: 6px 20px; }
        @media (max-width: 860px) {
            .lp-foot-grid { grid-template-columns: 1fr; gap: 32px; padding-top: 48px; }
        }
    </style>
</head>
<body class="lp">
    <header class="lp-top">
        <div class="lp-wrap">
            <a class="lp-logo" href="{{ "~/" | href }}" aria-label="Glas poduzetnika - naslovnica">
                <img src="{{ "~/UgpTheme/assets/img/header-logo.png" | href }}" alt="Glas poduzetnika">
            </a>
            <nav class="lp-nav" id="lp-nav" aria-label="Sadržaj stranice"></nav>
            <a class="lp-btn lp-btn-primary lp-btn-sm lp-top-cta" href="https://forms.gle/7Cv1YMYi3HrU3kbF7" target="_blank" rel="noopener">Prijavi se</a>
        </div>
    </header>

    {% render_section "Header", required: false %}

    <main>
        {% render_section "Messages", required: false %}
        {% render_body %}
    </main>

    <footer class="lp-foot">
        <div class="lp-wrap">
            <div class="lp-foot-grid">
                <div>
                    <a class="lp-foot-logo" href="{{ "~/" | href }}">
                        <img src="{{ "~/UgpTheme/assets/img/header-logo.png" | href }}" alt="Glas poduzetnika">
                    </a>
                    <p class="lp-foot-about">Udruga Glas poduzetnika okuplja poduzetnike koji vjeruju da se konkurentnost gradi znanjem, a ne čekanjem da netko drugi riješi problem.</p>
                </div>
                <div>
                    <h4>Udruga</h4>
                    <ul>
                        <li><a href="{{ "~/o-nama" | href }}">O nama</a></li>
                        <li><a href="{{ "~/najave-evenata" | href }}">Događanja i konferencije</a></li>
                        <li><a href="{{ "~/register" | href }}">Učlani se</a></li>
                        <li><a href="{{ "~/Login" | href }}">Prijava za članove</a></li>
                    </ul>
                </div>
                <div>
                    <h4>Pratite nas</h4>
                    <div class="lp-social">
                        <a href="https://www.facebook.com/glas.poduzetnika/" aria-label="Facebook"><i class="fab fa-facebook-f"></i></a>
                        <a href="https://www.facebook.com/groups/glaspoduzetnika/" aria-label="Facebook grupa"><i class="fas fa-users"></i></a>
                        <a href="https://twitter.com/poduzetnika" aria-label="X / Twitter"><i class="fab fa-twitter"></i></a>
                        <a href="https://www.linkedin.com/company/glas-poduzetnika" aria-label="LinkedIn"><i class="fab fa-linkedin-in"></i></a>
                        <a href="https://www.youtube.com/channel/UCK48gv8BTJOiH1QDPfa5eLQ" aria-label="YouTube"><i class="fab fa-youtube"></i></a>
                        <a href="https://www.instagram.com/glas.poduzetnika/" aria-label="Instagram"><i class="fab fa-instagram"></i></a>
                    </div>
                </div>
            </div>
            <div class="lp-foot-bottom">
                <span>© {{ "now" | date: "%Y" }} Udruga Glas Poduzetnika. Sva prava pridržana.</span>
                <nav class="lp-legal" aria-label="Pravne informacije">
                    <a href="{{ "~/pravila-privatnosti" | href }}">Pravila privatnosti</a>
                    <a href="{{ "~/uvjeti-koristenja" | href }}">Uvjeti korištenja</a>
                    <a href="{{ "~/izjava-o-kolacicima" | href }}">Izjava o kolačićima</a>
                    <a href="{{ "~/opci-uvjeti" | href }}">Opći uvjeti</a>
                </nav>
            </div>
        </div>
    </footer>

    {% resources type: "FootScript" %}
    <script>
        (function () {
            // Builds the top navigation from every body element that has both an id and data-nav="Label".
            var nav = document.getElementById('lp-nav');
            if (!nav) return;
            var links = [];
            document.querySelectorAll('[data-nav][id]').forEach(function (s) {
                var a = document.createElement('a');
                a.href = '#' + s.id;
                a.textContent = s.getAttribute('data-nav');
                nav.appendChild(a);
                links.push({ a: a, s: s });
            });
            if (!links.length || !('IntersectionObserver' in window)) return;
            var io = new IntersectionObserver(function (entries) {
                entries.forEach(function (e) {
                    if (!e.isIntersecting) return;
                    links.forEach(function (l) { l.a.classList.toggle('is-active', l.s === e.target); });
                });
            }, { rootMargin: '-40% 0px -55% 0px' });
            links.forEach(function (l) { io.observe(l.s); });
        })();
    </script>
</body>
</html>

Content__LandingPage.Content:
{% layout "Layout__LandingPage" %}
{% assign lp = Model.ContentItem.Content.LandingPage %}
{% assign reg = lp.Registration.Url %}
{% assign regText = lp.Registration.Text | default: "Prijavi se besplatno" %}
{% assign img = lp.Image.Paths.first %}

{% if lp.Subtitle.Text != blank %}{% meta name: "description", content: lp.Subtitle.Text %}{% endif %}
{% meta property: "og:title", content: Model.ContentItem.DisplayText %}
{% if img %}{% assign ogImage = img | asset_url | resize_url: width: 1200 | absolute_url %}{% meta property: "og:image", content: ogImage %}{% endif %}

{% zone "Header" %}
<header class="lp-hero">
    <div class="lp-wrap lp-hero-grid">
        <div>
            {% if lp.Eyebrow.Text != blank %}<p class="lp-eyebrow">{{ lp.Eyebrow.Text }}</p>{% endif %}
            <h1>{{ Model.ContentItem.DisplayText }}</h1>
            {% if lp.Subtitle.Text != blank %}<p class="lp-sub">{{ lp.Subtitle.Text }}</p>{% endif %}
            <ul class="lp-meta">
                {% if lp.When.Text != blank %}<li><i class="far fa-calendar-alt"></i> {{ lp.When.Text }}</li>{% endif %}
                {% if lp.Where.Text != blank %}<li><i class="fas fa-map-marker-alt"></i> {{ lp.Where.Text }}</li>{% endif %}
                {% if lp.Price.Text != blank %}<li><i class="fas fa-ticket-alt"></i> {{ lp.Price.Text }}</li>{% endif %}
            </ul>
            <div class="lp-actions">
                {% if reg != blank %}<a class="lp-btn lp-btn-primary" href="{{ reg }}" target="_blank" rel="noopener">{{ regText }} <i class="fas fa-arrow-right"></i></a>{% endif %}
                <a class="lp-btn lp-btn-ghost" href="#sadrzaj">Saznaj više</a>
            </div>
        </div>
        {% if img %}
        <figure class="lp-hero-media" style="margin:0">
            <img src="{{ img | asset_url | resize_url: width: 900 }}" alt="{{ Model.ContentItem.DisplayText }}">
        </figure>
        {% endif %}
    </div>
</header>
{% endzone %}

<div id="sadrzaj">
    {{ Model.Content.HtmlBodyPart | shape_render }}
</div>

{% if reg != blank %}
<section class="lp-cta" id="prijava">
    <div class="lp-wrap">
        <h2>{{ lp.CtaTitle.Text | default: "Vidimo se uživo" }}</h2>
        <p>{{ lp.CtaText.Text | default: "Prijave su otvorene." }}</p>
        <a class="lp-btn lp-btn-primary" href="{{ reg }}" target="_blank" rel="noopener">{{ regText }} <i class="fas fa-arrow-right"></i></a>
    </div>
</section>
{% endif %}
